int isAnagram(const char a[], const char b[]) {
  int freq[26] = {0};
  for (int i = 0; a[i] != '\0'; i++) {
    char c = a[i];
    if (c >= 'A' && c <= 'Z') c = c - 'A' + 'a';
    if (c >= 'a' && c <= 'z') freq[c - 'a']++;
  }
  for (int i = 0; b[i] != '\0'; i++) {
    char c = b[i];
    if (c >= 'A' && c <= 'Z') c = c - 'A' + 'a';
    if (c >= 'a' && c <= 'z') freq[c - 'a']--;
  }
  for (int i = 0; i < 26; i++) if (freq[i] != 0) return 0;
  return 1;
}

