int isPrime(int n) {
  if (n <= 1) return 0;
  if (n <= 3) return 1;
  if (n % 2 == 0) return 0;
  for (int d = 3; d * d <= n; d += 2) {
    if (n % d == 0) return 0;
  }
  return 1;
}

int gcd2(int a, int b) {
  while (b != 0) {
    int t = b;
    b = a % b;
    a = t;
  }
  return a < 0 ? -a : a;
}

int gcdArray(int nums[], int size) {
  int res = nums[0];
  for (int i = 1; i < size; i++) res = gcd2(res, nums[i]);
