}

int insertAt(int nums[], int size, int index, int val, int capacity) {
  if (index < 0 || index > size || size + 1 > capacity) return size;
  for (int i = size; i > index; i--) nums[i] = nums[i - 1];
  nums[index] = val;
  return size + 1;
}

